import XCTest
#if SWIFT_PACKAGE
@testable import LockerCore
#else
@testable import Locker
#endif

final class ArchiveTests: VaultTestCase {
    // Small, offline fixtures generated from the strings “Exemple” and “Note”.
    static let zip = ""

    func fixture(_ name: String, _ bytes: String) throws -> URL {
        let url = location(name)
        try XCTUnwrap(Data(base64Encoded: bytes)).write(to: url)
        return url
    }

    func testExtractsOnlyIntoDestinationAndKeepsFoldersAfterReopen() async throws {
        let source = try VaultStore(root: location("origine"), keys: VaultKeys(), create: true)
        let targetKeys = VaultKeys()
        let root = location("destination")
        let target = try VaultStore(root: root, keys: targetKeys, create: true)
        let folder = try await target.createFolder("Famille")
        let archive = try fixture("import.ZIP", Self.zip)
        let plain = location("autre.txt")
        try Data([9]).write(to: plain)
        try await target.extractSelection([archive, plain], folder: folder)
        let library = try await VaultStore(root: root, keys: targetKeys).library()
        XCTAssertEqual(library.documents.count, 3)
        XCTAssertTrue(library.folders.contains("Famille/vide"))
        XCTAssertEqual(Set(library.documents(in: folder).map(\.labels.name)), ["note.txt", "autre.txt"])
        let nested = try XCTUnwrap(library.documents(in: "Famille/Documents/Factures").first)
        let contents = try await target.preview(nested.id)
        XCTAssertEqual(contents, Data("Exemple".utf8))
        let untouched = try await source.list()
        XCTAssertTrue(untouched.isEmpty)
        let pending = await target.pending
        XCTAssertNotNil(pending[nested.id])
        for url in try FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: nil) {
            XCTAssertNil(try Data(contentsOf: url).range(of: Data("Exemple".utf8)))
        }
    }

    func testFailedOrLockedExtractionPublishesNothing() async throws {
        let root = location("coffre")
        let store = try VaultStore(root: root, keys: VaultKeys(), create: true)
        let zip = try fixture("correct.zip", Self.zip)
        let broken = location("incorrect.zip")
        try Data("Fichier fictif".utf8).write(to: broken)
        do { try await store.extractSelection([zip, broken], folder: ""); XCTFail("Archive illisible acceptée") } catch {}
        let library = try await store.library()
        let pending = await store.pending
        XCTAssertTrue(library.documents.isEmpty && library.folders.isEmpty && pending.isEmpty)
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: root.path), ["catalog.v1"])
        store.gate.revoke()
        do { try await store.extractSelection([zip], folder: ""); XCTFail("Coffre verrouillé") } catch VaultError.locked {}
    }

    func testCompressedTarSingleStreamsAnd7z() async throws {
        let fixtures = [
            ("lot.tar.gz", "H4sIAAAAAAAA/+3OMQrCQBAF0BzFE2iiIZ5A7xHCdgqSnUCO72IlWglGU7zX/GGa/8/9ENOY8i5Sjm3MUX1fXXRt+8jiNYvj013+TbM/dNWmXmDLmylHP5b6X3St0GlO19sl/XsGAAAAAAAAAAAAH7oDVzc64AAoAAA=", "test.txt", "Factures"),
            ("texte.txt.gz", "H4sIAAAAAAAA/3OtSM0tyEkFAMME0VQHAAAA", "texte.txt", ""),
            ("texte.txt.bz2", "QlpoOTFBWSZTWQD9s/AAAAAFgAIAAgZAQCAAMMAIYaJhAwu5IpwoSAB+2fgA", "texte.txt", ""),
            ("texte.txt.xz", "/Td6WFoAAATm1rRGAgAhARYAAAB0L+WjAQAGRXhlbXBsZQAAiTH11LRVNYwAAR8HFi64cx+2830BAAAAAARZWg==", "texte.txt", ""),
            ("lot.7z", "", "test.txt", "Factures")
        ]
        for (name, encoded, expected, folder) in fixtures {
            let store = try VaultStore(root: location(UUID().uuidString), keys: VaultKeys(), create: true)
            let file = try fixture(name, encoded)
            try await store.extractSelection([file], folder: "")
            let docs = try await store.list()
            XCTAssertEqual(docs.map(\.labels.name), [expected], name)
            let item = try XCTUnwrap(docs.first)
            XCTAssertEqual(item.labels.folder, folder, name)
            let content = try await store.preview(item.id)
            XCTAssertEqual(content, Data("Exemple".utf8), name)
        }
    }
}
